// Genealogiq APP — Tier 1 PWA service worker (installability + branding only).
//
// Hand-written, not generated by a build plugin: this app's Next.js config
// defaults to Turbopack (see next dev/build with no --webpack flag), and the
// current PWA tooling (next-pwa, @serwist/next's webpack plugin) doesn't run
// under Turbopack. A static file avoids that mismatch entirely.
//
// Scope is deliberately narrow:
//  - Precache a fixed list of visitor-agnostic static assets (fonts, brand
//    images, manifest icons) plus the offline fallback page.
//  - On navigation, always hit the network first; only fall back to the
//    cached offline page when the network fetch fails.
//  - Everything else (protected pages, Server Actions, /api/*, per-viewer
//    profile pages) is never intercepted — requests fall through to the
//    browser's normal network handling untouched.
const CACHE_NAME = "giq-static-v1"

const PRECACHE_URLS = [
  "/offline",
  "/manifest.webmanifest",
  "/icons/icon-192.png",
  "/icons/icon-512.png",
  "/icons/icon-512-maskable.png",
  "/icons/apple-touch-icon.png",
  "/logo-dark.png",
  "/logo-light.png",
  "/tree-dark.png",
  "/tree-light.png",
  "/fonts/inter/inter-latin-wght-normal.woff2",
  "/fonts/inter/inter-latin-wght-italic.woff2",
]

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(CACHE_NAME)
      .then((cache) => cache.addAll(PRECACHE_URLS))
      .then(() => self.skipWaiting())
  )
})

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((names) =>
        Promise.all(
          names
            .filter((name) => name !== CACHE_NAME)
            .map((name) => caches.delete(name))
        )
      )
      .then(() => self.clients.claim())
  )
})

self.addEventListener("fetch", (event) => {
  const { request } = event

  if (request.mode === "navigate") {
    event.respondWith(
      fetch(request).catch(() => caches.match("/offline"))
    )
    return
  }

  if (
    request.method === "GET" &&
    new URL(request.url).origin === self.location.origin &&
    PRECACHE_URLS.includes(new URL(request.url).pathname)
  ) {
    event.respondWith(
      caches.match(request).then(
        (cached) =>
          cached ||
          fetch(request).then((response) => {
            const copy = response.clone()
            caches.open(CACHE_NAME).then((cache) => cache.put(request, copy))
            return response
          })
      )
    )
  }

  // Anything else (protected pages, Server Actions, /api/*, per-viewer
  // profile pages) is left alone — no respondWith, no interception.
})
